105	    kernelParameters.put(IMPORTS, new DefaultJVMVariables().getImports());
106	    kernelParameters = getDefaultConnectionString(beakerXSystem, kernelParameters);
107	    return new EvaluatorParameters(kernelParameters);
108	  }
