131	                      DEFAULT_DATASOURCE,
132	                      "<sourceName=jdbc:[dbEngine]:[subsubprotocol:][databaseName]>",
133	                      new DefaultDataSourcesMagicCommand(kernel)));
134	    }
135	  }
