package com.twosigma.beakerx.sql.magic.command;

import com.twosigma.beakerx.BeakerXClient;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class DataSourceParamResolverImpl implements DataSourceParamResolver {

  private BeakerXClient client;

  public DataSourceParamResolverImpl(BeakerXClient client) {
    this.client = client;
  }

  @Override
  public String resolve(String jdbcTemplate) {
    Pattern pattern = Pattern.compile("\\{\\$beakerx\\.(.*?)\\}");
    Matcher matcher = pattern.matcher(jdbcTemplate);
    while (matcher.find()) {
      String variableName = matcher.group(1);
      String value = (String) client.get(variableName);
      jdbcTemplate = jdbcTemplate.replace("{$beakerx." + variableName + "}", value);
    }
    return jdbcTemplate;
  }
}
